_record = 12
_raw_cache: dict[tuple[int, int], bytes] = {}


def bucket_raw(key: tuple[int, int]) -> bytes:
    cached = _raw_cache.get(key)
    if cached is not None:
        return cached
    hexs = _BUCKETS.get(key)
    if hexs is None:
        return b""
    raw = bytes.fromhex(hexs)
    _raw_cache[key] = raw
    return raw


def contains(digest: str, arity: int, slots: int) -> bool:
    raw = bucket_raw((arity, slots))
    if not raw:
        return False
    needle = bytes.fromhex(digest)
    position = raw.find(needle)
    while position != -1:
        if position % _record == 0:
            return True
        position = raw.find(needle, position + 1)
    return False


